def check_equation(a_B, a_T, a_S):
    """Checks if 2^a_B + 3^a_T + 1 = 6^a_S"""
    lhs = 2**a_B + 3**a_T + 1
    rhs = 6**a_S
    return lhs == rhs

solutions = []
for a_B in range(1, 6):
    for a_T in range(1, 6):
        for a_S in range(1, 6):
            if check_equation(a_B, a_T, a_S):
                # Calculate B, T, S for the solution
                B = 2**a_B + 1
                T = 3**a_T + 1
                S = 6**a_S + 1
                solutions.append((B, T, S, a_B, a_T, a_S))

print("Found solutions (B, T, S, a_B, a_T, a_S):")
for sol in solutions:
    print(sol)

# Also list the equation check results explicitly for verification
print("\nTotal solutions found:", len(solutions))

def check_power_of_6(N):
    if N <= 0:
        return None
    if N == 1:
        return 0

    # Check for divisibility by 2 and 3
    if N % 2 != 0 or N % 3 != 0:
        return None

    k = 0
    temp = N
    while temp > 1:
        if temp % 6 != 0:
            return None
        temp //= 6
        k += 1
    return k

# Search for a_B = a_T = a, checking for a > 5
# We check up to a=10 to keep computation time reasonable, but this is an exploratory search.
max_a = 10
solutions = []

print("Searching for solutions where a_B = a_T = a and a > 5:")
for a in range(1, max_a + 1):
    N = pow(2, a) + pow(3, a) + 1
    a_S = check_power_of_6(N)

    if a_S is not None:
        if a > 5:
            solutions.append((a, a, a_S))
        else:
            # Record the non-qualifying solutions for completeness/comparison
            pass 

if not solutions:
