    for a in range(1, 24):
        for b in range(1, 15):
            if 2**a + 3**b == target:
                print(f"a={a}, b={b}")

solve_c9()

def solve_c_up_to_15():
    for c in range(1, 16):
        target = 6**c - 1
        for b in range(1, 20):
            pow3b = 3**b
            if pow3b >= target:
                break
            rem = target - pow3b
            if rem > 0 and (rem & (rem - 1) == 0):
                a = rem.bit_length() - 1
                if a >= 1:
                    print(f"a={a}, b={b}, c={c}")

solve_c_up_to_15()

